bash -lc cat > /mnt/data/build_spa.py <<'PY'
import re, json, pathlib, unicodedata, textwrap, shutil, zipfile, html
from datetime import datetime

SRC = pathlib.Path('/mnt/data/report.md')
OUT = pathlib.Path('/mnt/data/gourmet-meal-plan-spa')
if OUT.exists():
    shutil.rmtree(OUT)
(OUT/'assets/js').mkdir(parents=True)
(OUT/'assets/css').mkdir(parents=True)
(OUT/'assets/icons').mkdir(parents=True)
md = SRC.read_text(encoding='utf-8')

# Utility functions

def clean(s):
    s = s.replace('\u00a0', ' ').replace('‑','-').replace('–','-').replace('—','-')
    s = re.sub(r'【[^】]+】', '', s)
    return s.strip()

def strip_md(s):
    s = clean(s)
    s = re.sub(r'^#+\s*', '', s)
    s = re.sub(r'\*\*(.*?)\*\*', r'\1', s)
    s = re.sub(r'\*(.*?)\*', r'\1', s)
    return s.strip()

def slugify(s):
    s = unicodedata.normalize('NFKD', s).encode('ascii','ignore').decode('ascii')
    s = s.lower()
    s = re.sub(r'[^a-z0-9]+','-',s).strip('-')
    return s or 'item'

# Extract sections by top-level headings
sections = {}
for m in re.finditer(r'(?m)^#\s+(.*)$', md):
    title = strip_md(m.group(1))
    start = m.end()
    # find next top level heading
    n = re.search(r'(?m)^#\s+', md[start:])
    end = start + n.start() if n else len(md)
    sections[title] = md[start:end].strip()

# Knowledge map: first section before # 1
km_text = md.split('# 1. Executive Summary',1)[0].replace('# User Flavor Knowledge Map','').strip()
knowledge_map = {}
# Known section names
km_names = [
    'Cuisines & Cultural Inspirations','Dominant Flavor Profiles','Textures',
    'Key Ingredients & Spices','Preferred Techniques','Overall Taste DNA','How This Will Guide the Month'
]
for i, name in enumerate(km_names):
    # find bold heading
    pat = r'\*\*' + re.escape(name) + r'\*\*'
    m = re.search(pat, km_text)
    if not m: 
        continue
    start = m.end()
    if i + 1 < len(km_names):
        next_pat = r'\*\*' + re.escape(km_names[i+1]) + r'\*\*'
        n = re.search(next_pat, km_text[start:])
        end = start + n.start() if n else len(km_text)
    else:
        end = len(km_text)
    block = km_text[start:end].strip()
    items=[]
    # bullet items with bold label
    for line in block.splitlines():
        line=line.strip()
        if not line:
            continue
        if line.startswith('-'):
            line=line[1:].strip()
            bm=re.match(r'\*\*(.*?):\*\*\s*(.*)$', line)
            if bm:
                items.append({'label': clean(bm.group(1)), 'description': clean(bm.group(2))})
            else:
                items.append({'label':'', 'description': strip_md(line)})
        elif not items and line:
            # paragraph
            items.append({'label':'', 'description': strip_md(line)})
        elif line:
            # continuation of previous paragraph
            if items:
                items[-1]['description'] += ' ' + strip_md(line)
    knowledge_map[name]=items

# Executive summary
exec_match = re.search(r'# 1\. Executive Summary\s*(.*?)\n\s*# 2\.', md, re.S)
executive_summary = clean(exec_match.group(1)) if exec_match else ''

# Weekly overviews
wo_match = re.search(r'# 2\. Weekly Overviews\s*(.*?)\n\s*# 3\.', md, re.S)
weekly_overviews=[]
if wo_match:
    block=wo_match.group(1)
    for m in re.finditer(r'(?m)^##\s+Week\s*(\d+)\s*[–-]\s*(.*)$', block):
        week=int(m.group(1)); title=clean(f"Week {week} - {m.group(2)}")
        start=m.end();
        n=re.search(r'(?m)^##\s+Week\s*\d+', block[start:])
        end=start+n.start() if n else len(block)
        sub=block[start:end]
        theme=''
        tm=re.search(r'\*\*Theme:\*\*\s*(.*)', sub)
        if tm: theme=clean(tm.group(1))
        highlights=[]
        hm = re.search(r'\*\*Highlights:\*\*\s*(.*)', sub, re.S)
        hblock=hm.group(1) if hm else sub
        for line in hblock.splitlines():
            line=line.strip()
            if line.startswith('-'):
                highlights.append(strip_md(line[1:].strip()))
        weekly_overviews.append({'week':week,'title':title,'theme':theme,'highlights':highlights})

# Daily plans tables
dp_match = re.search(r'# 3\. Daily Meal Plans\s*(.*?)\n\s*# 4\.', md, re.S)
daily_plans=[]
if dp_match:
    block=dp_match.group(1)
    for m in re.finditer(r'(?m)^###\s+Week\s*(\d+)\s+Daily Plan', block):
        week=int(m.group(1)); start=m.end()
        n=re.search(r'(?m)^###\s+Week\s*\d+\s+Daily Plan', block[start:])
        end=start+n.start() if n else len(block)
        sub=block[start:end]
        lines=[ln.strip() for ln in sub.splitlines() if ln.strip().startswith('|')]
        # Skip header and separator
        for line in lines[2:]:
            cells=[strip_md(c.strip()) for c in line.strip('|').split('|')]
            if len(cells)>=5:
                day, breakfast, lunch, dinner, snack = cells[:5]
                daily_plans.append({'week':week,'day':day,'breakfast':breakfast,'lunch':lunch,'dinner':dinner,'snackDessert':snack})

# Recipes
recipe_block_match = re.search(r'# 4\. Full Recipes\s*(.*?)\n\s*# 5\. Master Weekly Shopping Lists', md, re.S)
recipes=[]
recipe_intro=''
if recipe_block_match:
    rblock=recipe_block_match.group(1).strip()
    parts=re.split(r'\n(?=##\s+)', rblock)
    if parts and not parts[0].startswith('## '):
        recipe_intro=clean(parts[0])
        parts=parts[1:]
    for p in parts:
        if not p.strip().startswith('## '):
            continue
        lines=p.strip().splitlines()
        header=strip_md(lines[0])
        if '(' in header and header.endswith(')'):
            name=header[:header.rfind('(')].strip()
            cuisine=header[header.rfind('(')+1:-1].strip()
        else:
            name=header.strip(); cuisine=''
        text='\n'.join(lines[1:]).strip()
        # parse summary row
        servings=active=total=''
        sm=re.search(r'\*\*Servings:\*\*\s*([^\n ]+)', text)
        if sm: servings=clean(sm.group(1))
        am=re.search(r'\*\*Active time:\*\*\s*([^\n ]+)', text)
        if am: active=clean(am.group(1))
        tm=re.search(r'\*\*Total time:\*\*\s*([^\n]+)', text)
        if tm: total=clean(tm.group(1))
        # extract titled sections
        def sect(title, end_titles):
            pat=r'\*\*'+re.escape(title)+r'\*\*'
            mm=re.search(pat, text)
            if not mm: return ''
            st=mm.end()
            ends=[]
            for et in end_titles:
                em=re.search(r'\*\*'+re.escape(et)+r'\*\*', text[st:])
                if em: ends.append(st+em.start())
            en=min(ends) if ends else len(text)
            return text[st:en].strip()
        mise_block=sect('Mise en place (≈30 min)', ['Ingredients','Method','Why this works:','Plating & Pairing:'])
        # Use flexible for mise headings including different time
        if not mise_block:
            mm=re.search(r'\*\*Mise[^\n]*\*\*', text)
            if mm:
                st=mm.end();
                em=re.search(r'\n\*\*Ingredients\*\*', text[st:])
                mise_block=text[st:st+em.start()].strip() if em else text[st:].strip()
        ing_block=sect('Ingredients', ['Method','Why this works:','Plating & Pairing:','Plating / Serving'])
        if not ing_block:
            mm=re.search(r'\*\*Ingredients\*\*', text)
            if mm:
                st=mm.end(); em=re.search(r'\n\*\*Method\*\*', text[st:])
                ing_block=text[st:st+em.start()].strip() if em else text[st:].strip()
        method_block=sect('Method', ['Why this works:','Plating & Pairing:','Plating / Serving'])
        if not method_block:
            mm=re.search(r'\*\*Method:?\*\*', text)
            if mm:
                st=mm.end(); em=re.search(r'\n\*\*Why this works:', text[st:])
                method_block=text[st:st+em.start()].strip() if em else text[st:].strip()
        why=''
        wm=re.search(r'\*\*Why this works:\*\*\s*(.*?)(?:\n\s*\*\*Plating[^*]*\*\*|\Z)', text, re.S)
        if wm: why=clean(wm.group(1))
        plating=''
        pm=re.search(r'\*\*Plating[^*]*\*\*\s*(.*)', text, re.S)
        if pm: plating=clean(pm.group(1))
        # If recipe base has no sections, method may be direct paragraph
        def bullet_lines(block):
            out=[]
            for ln in block.splitlines():
                ln=ln.strip()
                if not ln: continue
                if ln.startswith('-'):
                    out.append(strip_md(ln[1:].strip()))
                else:
                    out.append(strip_md(ln))
            return out
        def numbered_lines(block):
            out=[]
            buf=''
            for ln in block.splitlines():
                ln=ln.strip()
                if not ln: continue
                mnum=re.match(r'^(\d+)\.\s*(.*)', ln)
                if mnum:
                    if buf: out.append(strip_md(buf)); buf=''
                    buf=mnum.group(2)
                else:
                    if buf: buf += ' ' + ln
                    else: buf=ln
            if buf: out.append(strip_md(buf))
            return out
        recipes.append({
            'id': slugify(name), 'name': clean(name), 'cuisine': clean(cuisine),
            'servings': servings, 'activeTime': active, 'totalTime': total,
            'miseEnPlace': bullet_lines(mise_block),
            'ingredients': bullet_lines(ing_block),
            'method': numbered_lines(method_block),
            'whyThisWorks': why, 'plating': plating,
            'fullMarkdown': clean(p.strip())
        })

# Shopping lists
sl_match=re.search(r'# 5\. Master Weekly Shopping Lists\s*(.*?)\n\s*# 6\.', md, re.S)
shopping_lists=[]
if sl_match:
    block=sl_match.group(1)
    for m in re.finditer(r'(?m)^##\s+Week\s*(\d+)\s+Shopping List', block):
        week=int(m.group(1)); start=m.end()
        n=re.search(r'(?m)^##\s+Week\s*\d+\s+Shopping List', block[start:])
        end=start+n.start() if n else len(block)
        sub=block[start:end]
        categories=[]
        # category lines **Produce:** item list
        for cm in re.finditer(r'\*\*([^:*]+):\*\*\s*(.*?)(?=\n\s*\*\*[^:*]+:\*\*|\Z)', sub, re.S):
            cat=clean(cm.group(1)); contents=clean(cm.group(2))
            # split by commas but keep parentheses okay
            items=[]
            # semicolon too
            for item in re.split(r',\s*(?=(?:[^()]|\([^)]*\))*$)|;\s*', contents):
                item=strip_md(item)
                if item: items.append(item)
            categories.append({'category':cat,'items':items})
        shopping_lists.append({'week':week,'categories':categories})

# Flatten meal plan data
meal_data={
    'meta': {
        'title': 'Gourmet Meal Plan SPA',
        'subtitle': 'A dark-mode personal chef dashboard for the one-month gourmet plan',
        'generatedAt': datetime.utcnow().isoformat()+'Z',
        'sourceReport': 'report.md',
        'validationNotes': [
            'Data extracted from the previously generated markdown meal-plan report.',
            'Recipe fullMarkdown fields preserve the complete source text for every recipe, including metric units, science notes, and pairing notes.',
            'Interactive UI uses the structured fields while retaining fullMarkdown for auditability.'
        ]
    },
    'knowledgeMap': knowledge_map,
    'executiveSummary': executive_summary,
    'weeklyOverviews': weekly_overviews,
    'dailyPlans': daily_plans,
    'recipes': recipes,
    'shoppingLists': shopping_lists,
    'recipeIntro': recipe_intro
}

# write data.js
js_data = '/*\n  Gourmet Meal Plan SPA - Data Store\n  ------------------------------------------------------------\n  This file is intentionally static and self-contained. It exposes\n  `window.MEAL_PLAN_DATA` so the SPA can run from file://, GitHub\n  Pages, or any static host without a build step or backend.\n*/\n\nwindow.MEAL_PLAN_DATA = ' + json.dumps(meal_data, ensure_ascii=False, indent=2) + ';\n'
(OUT/'assets/js/data.js').write_text(js_data, encoding='utf-8')

# CSS
css='''/*
  Gourmet Meal Plan SPA - Custom CSS Layer
  ------------------------------------------------------------
  Tailwind CSS handles most visual styling via utility classes. This
  file only contains small app-level refinements that are easier to
  express once: print behavior, scrollbars, modal containment, and
  a few chef-inspired ambient effects.
*/
:root {
  color-scheme: dark;
  --chef-ink: #0b0b10;
  --chef-card: rgba(24, 24, 32, 0.82);
  --chef-line: rgba(255, 255, 255, 0.12);
  --chef-gold: #f6b45c;
  --chef-rose: #f97373;
}
html { scroll-behavior: smooth; }
body {
  min-height: 100vh;
  background:
    radial-gradient(circle at top left, rgba(246, 180, 92, 0.16), transparent 34rem),
    radial-gradient(circle at 80% 20%, rgba(249, 115, 115, 0.10), transparent 28rem),
    linear-gradient(135deg, #0b0b10 0%, #12121a 44%, #17111a 100%);
}
[x-cloak] { display: none !important; }
.app-glass {
  backdrop-filter: blur(18px);
  background: rgba(15, 15, 22, 0.72);
  border: 1px solid var(--chef-line);
}
.recipe-prose p { margin: 0.5rem 0; }
.recipe-prose ol { list-style: decimal; padding-left: 1.25rem; }
.recipe-prose ul { list-style: disc; padding-left: 1.25rem; }
.recipe-prose li { margin: 0.25rem 0; }
.print-only { display: none; }
@media print {
  body { background: #fff !important; color: #111 !important; }
  .no-print { display: none !important; }
  .print-only { display: block !important; }
  .print-card { break-inside: avoid; border: 1px solid #ccc !important; background: #fff !important; color: #111 !important; }
  main { overflow: visible !important; }
  a { color: #111 !important; text-decoration: none !important; }
}
'''
(OUT/'assets/css/tailwind.css').write_text(css, encoding='utf-8')

# app.js
app_js = r'''/*
  Gourmet Meal Plan SPA - Alpine + Vanilla JavaScript Application
  ============================================================================
  Philosophy:
  - No build tools.
  - No server.
  - No external application framework beyond Alpine.js.
  - All data lives in assets/js/data.js as a static object.
  - All state that should survive refreshes (shopping-list checks) lives in localStorage.

  The code below deliberately uses plain, heavily-commented functions so a
  non-technical or lightly technical owner can modify labels, colors, or data
  behavior without learning a build pipeline.
*/

/**
 * Function preamble: normalizeText(value)
 * --------------------------------------------------------------------------
 * Objective:
 * Convert any human-facing string into a stable comparison key. This is used
 * for fuzzy recipe matching, searching, slug-like comparisons, and preserving
 * good behavior across accents, en-dashes, non-breaking spaces, and punctuation.
 *
 * Why it matters:
 * The meal plan contains rich culinary names with diacritics (Huancaína),
 * typographic punctuation (×, –), and shortened menu references ("Smoked Salmon
 * & Avocado Bagel") that should still resolve to the full recipe title.
 *
 * Assumptions:
 * The function is not meant for secure identifiers. It is a usability helper.
 */
function normalizeText(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[’‘]/g, "'")
    .replace(/[×]/g, ' x ')
    .replace(/[&]/g, ' and ')
    .replace(/[^a-zA-Z0-9]+/g, ' ')
    .toLowerCase()
    .trim();
}

/**
 * Function preamble: slugify(value)
 * --------------------------------------------------------------------------
 * Objective:
 * Produce a compact, URL-safe slug for recipes, sections, and localStorage keys.
 * This mirrors normalizeText but joins tokens with dashes.
 */
function slugify(value) {
  return normalizeText(value).replace(/\s+/g, '-');
}

/**
 * Function preamble: escapeHtml(value)
 * --------------------------------------------------------------------------
 * Objective:
 * Safely render plain text into HTML snippets generated by the app. This keeps
 * recipe text, data strings, and shopping items from accidentally becoming HTML.
 */
function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

/**
 * Function preamble: renderInlineMarkdown(value)
 * --------------------------------------------------------------------------
 * Objective:
 * Render the limited markdown syntax used in the generated meal plan. This is
 * intentionally small: it supports bold spans and preserves line breaks without
 * pulling in a full Markdown dependency.
 *
 * Design decision:
 * A no-dependency SPA should not add a markdown library. The parsed JSON already
 * contains structured arrays for most UI views. This helper only beautifies raw
 * recipe audit text when displayed.
 */
function renderInlineMarkdown(value) {
  return escapeHtml(value)
    .replace(/\*\*(.*?)\*\*/g, '<strong class="text-amber-200">$1</strong>')
    .replace(/\n/g, '<br>');
}

/**
 * Function preamble: mealPlanApp()
 * --------------------------------------------------------------------------
 * Objective:
 * Return the full Alpine.js component state and behavior for the SPA. Alpine
 * calls this function once from the root element in index.html. All routing,
 * filtering, modals, shopping checks, copy actions, and print states live here.
 *
 * Architecture:
 * - view: current top-level section (dashboard/calendar/week/day/recipes/shopping/knowledge)
 * - selectedDay / selectedWeek: contextual navigation state
 * - selectedRecipe: modal state
 * - query: recipe search text
 * - checkedItems: localStorage-backed map of shopping checkboxes
 */
function mealPlanApp() {
  return {
    data: window.MEAL_PLAN_DATA,
    view: 'dashboard',
    selectedWeek: 1,
    selectedDayIndex: 0,
    selectedRecipe: null,
    query: '',
    shoppingWeek: 1,
    toast: '',
    checkedItems: {},
    dayLabels: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
    mealSlots: [
      { key: 'breakfast', label: 'Breakfast', icon: '☕' },
      { key: 'lunch', label: 'Lunch', icon: '🥗' },
      { key: 'dinner', label: 'Dinner', icon: '🍽️' },
      { key: 'snackDessert', label: 'Optional Snack/Dessert', icon: '🍫' }
    ],

    /**
     * Function preamble: init()
     * ----------------------------------------------------------------------
     * Objective:
     * Initialize persistent state, normalize recipe indexes, and activate the
     * hash router. The app is intentionally URL-addressable so shared links like
     * #recipes or #day/2/4 open the intended view immediately.
     */
    init() {
      this.loadChecks();
      this.ensureRecipeIndex();
      this.readRoute();
      window.addEventListener('hashchange', () => this.readRoute());
    },

    /**
     * Function preamble: ensureRecipeIndex()
     * ----------------------------------------------------------------------
     * Objective:
     * Add runtime-only helpers to recipe objects: normalizedName and slug.
     * These fields make fuzzy menu-to-recipe matching fast and predictable.
     */
    ensureRecipeIndex() {
      this.data.recipes.forEach((recipe) => {
        recipe.normalizedName = normalizeText(recipe.name);
        recipe.slug = recipe.id || slugify(recipe.name);
      });
    },

    /**
     * Function preamble: navigate(target)
     * ----------------------------------------------------------------------
     * Objective:
     * Centralize route changes so buttons, keyboard shortcuts, and deep links all
     * use the same path format. This is client-side routing without page reloads.
     */
    navigate(target) {
      window.location.hash = target;
    },

    /**
     * Function preamble: readRoute()
     * ----------------------------------------------------------------------
     * Objective:
     * Interpret location.hash and update Alpine state. Supported routes:
     * #dashboard, #calendar, #week/1, #day/1/0, #recipes, #shopping/2,
     * #knowledge.
     */
    readRoute() {
      const raw = (window.location.hash || '#dashboard').replace(/^#/, '');
      const parts = raw.split('/').filter(Boolean);
      const page = parts[0] || 'dashboard';
      if (['dashboard', 'calendar', 'recipes', 'knowledge'].includes(page)) {
        this.view = page;
      } else if (page === 'week') {
        this.view = 'week';
        this.selectedWeek = Math.min(4, Math.max(1, Number(parts[1] || 1)));
      } else if (page === 'day') {
        this.view = 'day';
        this.selectedWeek = Math.min(4, Math.max(1, Number(parts[1] || 1)));
        this.selectedDayIndex = Math.min(6, Math.max(0, Number(parts[2] || 0)));
      } else if (page === 'shopping') {
        this.view = 'shopping';
        this.shoppingWeek = Math.min(4, Math.max(1, Number(parts[1] || 1)));
      } else {
        this.view = 'dashboard';
      }
      window.scrollTo({ top: 0, behavior: 'smooth' });
    },

    /**
     * Function preamble: currentWeekOverview()
     * ----------------------------------------------------------------------
     * Objective:
     * Return the selected week's descriptive theme and highlights. If data is
     * missing, return a safe empty object instead of throwing.
     */
    currentWeekOverview() {
      return this.data.weeklyOverviews.find((week) => week.week === this.selectedWeek) || { highlights: [] };
    },

    /**
     * Function preamble: weekDays(weekNumber)
     * ----------------------------------------------------------------------
     * Objective:
     * Return the seven menu entries for a week. The source data is flat for easy
     * search and export; this helper groups it for visual display.
     */
    weekDays(weekNumber) {
      return this.data.dailyPlans.filter((day) => day.week === Number(weekNumber));
    },

    /**
     * Function preamble: selectedDay()
     * ----------------------------------------------------------------------
     * Objective:
     * Return the selected day menu based on selectedWeek and selectedDayIndex.
     */
    selectedDay() {
      return this.weekDays(this.selectedWeek)[this.selectedDayIndex] || this.data.dailyPlans[0];
    },

    /**
     * Function preamble: mealToRecipe(mealName)
     * ----------------------------------------------------------------------
     * Objective:
     * Convert a meal name from the calendar into the most plausible full recipe.
     * It uses exact matching first, then bidirectional containment, then token
     * overlap. This handles shortened menu labels such as "Lucuma Tiramisu" and
     * longer recipe titles such as "Lucuma Tiramisu (Italian × Peruvian)".
     */
    mealToRecipe(mealName) {
      const needle = normalizeText(mealName);
      if (!needle) return null;
      let match = this.data.recipes.find((recipe) => recipe.normalizedName === needle);
      if (match) return match;
      match = this.data.recipes.find((recipe) => recipe.normalizedName.includes(needle) || needle.includes(recipe.normalizedName));
      if (match) return match;
      const tokens = needle.split(' ').filter((token) => token.length > 2);
      let best = null;
      let bestScore = 0;
      this.data.recipes.forEach((recipe) => {
        const score = tokens.reduce((sum, token) => sum + (recipe.normalizedName.includes(token) ? 1 : 0), 0);
        if (score > bestScore) {
          bestScore = score;
          best = recipe;
        }
      });
      return bestScore >= Math.min(3, tokens.length) ? best : null;
    },

    /**
     * Function preamble: openRecipeByMeal(mealName)
     * ----------------------------------------------------------------------
     * Objective:
     * Open the recipe modal from a calendar/day/week meal label. If no recipe can
     * be matched, display a helpful toast instead of failing silently.
     */
    openRecipeByMeal(mealName) {
      const recipe = this.mealToRecipe(mealName);
      if (recipe) {
        this.selectedRecipe = recipe;
      } else {
        this.showToast(`No full recipe was found for “${mealName}”.`);
      }
    },

    /**
     * Function preamble: filteredRecipes()
     * ----------------------------------------------------------------------
     * Objective:
     * Return recipes filtered by the user's search query across recipe name,
     * cuisine, ingredients, method, and science note. This makes the recipe
     * library useful for searches like "aji", "chocolate", or "sous-vide".
     */
    get filteredRecipes() {
      const q = normalizeText(this.query);
      if (!q) return this.data.recipes;
      return this.data.recipes.filter((recipe) => normalizeText([
        recipe.name,
        recipe.cuisine,
        recipe.ingredients.join(' '),
        recipe.method.join(' '),
        recipe.whyThisWorks,
        recipe.plating
      ].join(' ')).includes(q));
    },

    /**
     * Function preamble: shoppingListForWeek(weekNumber)
     * ----------------------------------------------------------------------
     * Objective:
     * Retrieve the categorized shopping list for a week. Returns a stable empty
     * list if the data is not present.
     */
    shoppingListForWeek(weekNumber) {
      const list = this.data.shoppingLists.find((week) => week.week === Number(weekNumber));
      return list ? list.categories : [];
    },

    /**
     * Function preamble: checkKey(week, category, item)
     * ----------------------------------------------------------------------
     * Objective:
     * Create a deterministic key for each shopping checkbox. It includes week,
     * category, and item text to avoid collisions between repeated ingredients.
     */
    checkKey(week, category, item) {
      return `week-${week}::${slugify(category)}::${slugify(item)}`;
    },

    /**
     * Function preamble: loadChecks()
     * ----------------------------------------------------------------------
     * Objective:
     * Load shopping checkbox state from localStorage. JSON parsing is wrapped in
     * a try/catch so a corrupted value never breaks the application.
     */
    loadChecks() {
      try {
        this.checkedItems = JSON.parse(localStorage.getItem('gourmet-shopping-checks') || '{}');
      } catch (_error) {
        this.checkedItems = {};
      }
    },

    /**
     * Function preamble: saveChecks()
     * ----------------------------------------------------------------------
     * Objective:
     * Persist shopping checkbox state in localStorage so checked items remain
     * checked after refreshes or browser restarts.
     */
    saveChecks() {
      localStorage.setItem('gourmet-shopping-checks', JSON.stringify(this.checkedItems));
    },

    /**
     * Function preamble: toggleCheck(key)
     * ----------------------------------------------------------------------
     * Objective:
     * Toggle a shopping item and immediately persist the result. Alpine's
     * reactivity updates the checkbox and strikethrough state in place.
     */
    toggleCheck(key) {
      this.checkedItems[key] = !this.checkedItems[key];
      this.saveChecks();
    },

    /**
     * Function preamble: copyShoppingList()
     * ----------------------------------------------------------------------
     * Objective:
     * Copy the currently selected week's shopping list as clean, categorized
     * plain text. The method uses the modern Clipboard API with a fallback toast
     * if the browser blocks clipboard access.
     */
    async copyShoppingList() {
      const lines = [`Week ${this.shoppingWeek} Shopping List`];
      this.shoppingListForWeek(this.shoppingWeek).forEach((category) => {
        lines.push('', category.category);
        category.items.forEach((item) => lines.push(`- ${item}`));
      });
      try {
        await navigator.clipboard.writeText(lines.join('\n'));
        this.showToast('Shopping list copied to clipboard.');
      } catch (_error) {
        this.showToast('Clipboard access was blocked; select and copy manually.');
      }
    },

    /**
     * Function preamble: resetShoppingWeek()
     * ----------------------------------------------------------------------
     * Objective:
     * Clear checkbox progress only for the currently selected week. This avoids
     * deleting progress for other weeks.
     */
    resetShoppingWeek() {
      const prefix = `week-${this.shoppingWeek}::`;
      Object.keys(this.checkedItems).forEach((key) => {
        if (key.startsWith(prefix)) delete this.checkedItems[key];
      });
      this.saveChecks();
      this.showToast(`Week ${this.shoppingWeek} checks cleared.`);
    },

    /**
     * Function preamble: shoppingProgress(weekNumber)
     * ----------------------------------------------------------------------
     * Objective:
     * Calculate checked/total shopping items for a week. This powers the small
     * progress pill in the shopping UI.
     */
    shoppingProgress(weekNumber) {
      const categories = this.shoppingListForWeek(weekNumber);
      let total = 0;
      let checked = 0;
      categories.forEach((category) => {
        category.items.forEach((item) => {
          total += 1;
          if (this.checkedItems[this.checkKey(weekNumber, category.category, item)]) checked += 1;
        });
      });
      return { checked, total, pct: total ? Math.round((checked / total) * 100) : 0 };
    },

    /**
     * Function preamble: printCurrentView()
     * ----------------------------------------------------------------------
     * Objective:
     * Trigger the browser print dialog. CSS media rules in assets/css/tailwind.css
     * simplify the page and hide navigation for a clean recipe/list printout.
     */
    printCurrentView() {
      window.print();
    },

    /**
     * Function preamble: exportData()
     * ----------------------------------------------------------------------
     * Objective:
     * Download the embedded JSON data for audit, backup, or future migration to
     * a richer app. This helps validate that no recipe content is trapped in UI.
     */
    exportData() {
      const blob = new Blob([JSON.stringify(this.data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'gourmet-meal-plan-data.json';
      a.click();
      URL.revokeObjectURL(url);
      this.showToast('Structured meal-plan JSON downloaded.');
    },

    /**
     * Function preamble: showToast(message)
     * ----------------------------------------------------------------------
     * Objective:
     * Display short, non-blocking feedback. The timeout clears the message so the
     * UI does not remain cluttered.
     */
    showToast(message) {
      this.toast = message;
      setTimeout(() => { this.toast = ''; }, 2400);
    },

    /**
     * Function preamble: recipeSectionCount(recipe)
     * ----------------------------------------------------------------------
     * Objective:
     * Small UI helper for showing how complete a recipe is. Because data.js also
     * preserves fullMarkdown, a recipe with few parsed bullets still has complete
     * source text available in the modal.
     */
    recipeSectionCount(recipe) {
      return ['miseEnPlace', 'ingredients', 'method'].reduce((sum, key) => sum + (recipe[key]?.length || 0), 0);
    },

    renderInlineMarkdown
  };
}
'''
