export const recipes = [{"title": "Artichoke Benedict with Trout (Peruvian × Nikkei)", "servings": null, "active_time": "", "total_time": "", "mise_en_place": ["**Station A – English muffins:** Mix whole‑wheat dough (250 g whole‑wheat flour, 250 g bread flour, 7 g yeast, 10 g sugar, 300 ml warm milk, 30 g butter, 5 g salt) and let proof; shape into 8 muffins, rest 20 min.", "**Station B – Artichokes & trout:** Trim and steam 4 large artichoke hearts (400 g), then slice into quarters; season 200 g smoked trout fillet and flake into bite‑sized pieces.", "**Station C – Hollandaise:** Juice 1 lemon (30 ml), dice 50 g cold butter, measure 3 egg yolks and 50 ml aji‑amarillo purée; set up bain‑marie.", "**Station D – Poaching setup:** Crack 8 fresh eggs into individual ramekins; bring a wide shallow pan of water to a gentle simmer with 30 ml vinegar.", "**Station E – Garnishes:** Chop 30 g chives and 10 g cilantro; prepare aji amarillo hollandaise ingredients and warm plates."], "ingredients": ["**For the muffins:** As per Station A above.", "**Protein & veg:** 4 steamed artichoke hearts (≈400 g), 200 g smoked trout fillet, 8 large eggs.", "**Hollandaise:** 3 egg yolks, 50 g cold unsalted butter cut into cubes, 30 ml lemon juice, 50 ml aji amarillo purée, 2 ml Dijon mustard, salt to taste.", "**Poaching liquor:** Water, 30 ml white vinegar.", "**Garnish:** Chopped chives, cilantro, freshly ground black pepper."], "method": ["**Cook muffins:** Preheat a heavy skillet over medium‑low heat. Roll the rested dough into 2 cm‑thick rounds using a ring cutter. Cook muffins dry (no fat) until golden on each side (≈5 min per side). Split and keep warm.", "**Steam artichokes:** If not already steamed, cook trimmed hearts in salted boiling water until tender (≈10 min); drain and sear in a hot pan with a drizzle of olive oil until lightly caramelised.", "**Prepare hollandaise:** In a bain‑marie over barely simmering water, whisk egg yolks with lemon juice and mustard until thick ribbons form. Slowly whisk in cold butter cubes one at a time until emulsified. Add aji amarillo purée; season with salt. Keep warm but not hot to avoid scrambling.", "**Poach eggs:** Create a gentle vortex in the poaching liquor and slide in one egg at a time. Cook 3 min for runny yolks. Remove with a slotted spoon to a paper towel.", "**Assemble:** Place a toasted muffin half on each plate. Top with seared artichoke quarters and flaked trout. Gently perch a poached egg on top and spoon over warm aji amarillo hollandaise. Sprinkle with chives, cilantro and black pepper."], "why_this_works": "** Whole‑wheat muffins provide nutty depth and fibre. Emulsifying butter into egg yolks over gentle heat yields a stable, velvety hollandaise; adding aji amarillo introduces fruity heat and vibrant colour without excess fat. Poaching eggs in acidulated water coagulates the whites quickly for neat spheres, while smoked trout delivers umami and omega‑3s.", "plating": "& Pairing:** Serve two halves per person on warm plates. Garnish with micro‑greens for colour. Pair with a glass of sparkling brut nature or a chilled chicha morada spritzer (sparkling water with purple‑corn reduction and lime) for a non‑alcoholic option."}, {"title": "Birria Ramen with Sous‑Vide Egg (Mexican × Japanese)", "servings": null, "active_time": "", "total_time": "", "mise_en_place": ["**Station A – Birria broth:** Toast 5 dried guajillo and 3 ancho chiles until fragrant; rehydrate in hot water. Sear 800 g lamb or beef chuck in a Dutch oven; gather aromatics (1 onion, 4 garlic cloves, 2 bay leaves, 5 g cumin seeds, 5 g coriander seeds).", "**Station B – Ramen tare:** Combine 60 ml tamari, 60 ml sake (optional), 30 ml mirin, 30 ml fish sauce and 30 ml rice vinegar.", "**Station C – Noodles & toppings:** Prepare 800 g fresh whole‑wheat ramen noodles; slice 200 g shiitake mushrooms, 100 g radishes, chop 30 g cilantro, slice 2 limes. Set up sous‑vide water bath at 63 °C for eggs."], "ingredients": ["**Birria:** 800 g grass‑fed lamb or beef chuck cut into chunks, 5 dried guajillo chiles, 3 dried ancho chiles, 1 onion, 4 garlic cloves, 1 stick cinnamon, 2 bay leaves, 5 g each cumin and coriander seeds, 500 ml beef stock, 500 ml water.", "**Ramen:** 800 g fresh whole‑wheat ramen noodles, 4 eggs (for sous‑vide), 200 g shiitake mushrooms, 100 g radishes, 100 g bean sprouts, 30 g cilantro, lime wedges.", "**Tare:** 60 ml tamari, 60 ml sake (omit or use 30 ml extra tamari for non‑alcoholic), 30 ml mirin or apple‑cider vinegar, 30 ml fish sauce, 30 ml rice vinegar.", "**Garnish:** 20 g toasted sesame seeds, 2 spring onions sliced."], "method": ["**Make birria:** Toast chiles briefly in a dry pan, then soak in 250 ml boiling water until soft. Blend with soaking liquid, onion, garlic, spices and a pinch of salt to a smooth paste. Sear meat in a Dutch oven until browned; add chile purée, cinnamon stick, bay leaves, stock and water. Bring to a simmer, cover and braise in a 150 °C oven for 4–5 hours until meat is tender. Shred meat and return to broth; adjust salt.", "**Prepare eggs:** Submerge eggs in a 63 °C sous‑vide bath for 45 min (for jammy yolks). Shock in ice water, then carefully crack and slide into bowls later.", "**Cook noodles & toppings:** Sauté mushrooms in a drop of sesame oil until browned; season lightly. Blanch ramen noodles in boiling water for 1 min (fresh) or until al dente; rinse briefly to stop cooking.", "**Assemble bowls:** Place 1 tbsp tare in each warmed bowl. Add noodles. Ladle over hot birria broth and shredded meat. Top with mushrooms, bean sprouts, sliced radish and cilantro. Gently add peeled sous‑vide egg. Finish with sesame seeds, spring onions and a squeeze of lime."], "why_this_works": "** Slow braising extracts collagen from chuck, producing a silky broth enriched with toasted chiles for deep, complex flavour. The tare concentrates umami (tamari, fish sauce) and balances acidity (vinegar) to season the broth just before serving. Sous‑vide eggs cooked at 63 °C achieve custardy yolks that meld into the soup, echoing the richness of traditional ramen.", "plating": "& Pairing:** Serve in deep bowls with long-handled chopsticks and spoons. The broth should be glossy with a gentle chile sheen. Pair with a crisp Kölsch beer (limit to one glass) or a chilled hibiscus‑lime agua fresca."}, {"title": "Brown Rice Risotto alla Parmigiana with Artichokes & Scallops (Italian)", "servings": null, "active_time": "", "total_time": "", "mise_en_place": ["**Station A – Rice:** Soak 300 g short‑grain brown rice in water for at least 30 min to soften the bran; drain.", "**Station B – Stock:** Heat 1.5 L vegetable or fish stock; keep warm on a back burner.", "**Station C – Vegetables:** Mince 1 shallot, slice 200 g mushrooms, quarter 2 steamed artichoke hearts (200 g), grate 80 g Parmigiano‑Reggiano.", "**Station D – Scallops:** Pat dry 8 large sea scallops (320 g) and season with sea salt; bring a sauté pan to medium‑high heat."], "ingredients": ["300 g short‑grain brown rice (soaked), 1.5 L hot stock (vegetable/fish), 1 shallot, 2 tbsp (30 ml) olive oil, 200 g mixed mushrooms, 200 g cooked artichoke hearts, 100 ml dry white wine, 80 g Parmigiano‑Reggiano, 20 g unsalted butter, 8 sea scallops (≈320 g total), 5 g fresh thyme, salt & black pepper."], "method": ["**Build the soffritto:** In a heavy saucepan over medium heat, sweat minced shallot in olive oil unti
...[truncated]...
 spicy artisanal salami (cured at home or nitrate‑free), 1 red bell pepper and 1 red onion; slice 200 g fresh mozzarella.", "**Station C – Rocoto honey:** Heat 50 g honey with 20 g rocoto paste until combined; cool."], "ingredients": ["250 g whole‑wheat flour, 250 g bread flour, 2 g yeast, 350 ml water, 10 g salt, 20 ml olive oil.", "Toppings: 400 g crushed tomatoes, 2 garlic cloves, oregano, 150 g spicy salami (homemade), 1 red bell pepper, 1 red onion, 200 g mozzarella, 50 g rocoto honey, 10 g chili flakes."], "method": ["**Prepare dough:** Mix ingredients and knead gently. Refrigerate in a covered container for 12 – 24 h. On baking day, divide and shape into balls; rest until puffy.", "**Preheat oven:** Heat a baking stone at 250 °C for at least 45 min. Stretch dough into 30 cm rounds.", "**Assemble pizza:** Spread a thin layer of tomato sauce. Top with salami, bell pepper, onion and mozzarella. Bake on the stone for 8 – 10 min until crust is crisp and toppings bubbly.", "**Finish:** Drizzle with rocoto honey and sprinkle with chili flakes and fresh oregano."], "why_this_works": "** Long fermentation develops flavour and elasticity in the dough. Baking on a preheated stone replicates a wood‑fired oven, producing a crisp bottom. Rocoto honey provides sweet heat that contrasts with spicy salami and tangy tomato sauce.", "plating": "& Pairing:** Slice and serve immediately. Pair with a dry Lambrusco or a berry‑infused sparkling water."}, {"title": "Whole‑Grain Pizza Diavola (Substitution for Non‑Meat Option)", "servings": null, "active_time": "", "total_time": "", "mise_en_place": [], "ingredients": [], "method": [], "why_this_works": null, "plating": null}, {"title": "Whole‑Grain Spaghetti Puttanesca with Ají Panca Seafood (Italian × Peruvian)", "servings": null, "active_time": "", "total_time": "", "mise_en_place": ["**Station A – Pasta:** Cook 400 g whole‑grain spaghetti in abundant salted water until al dente; reserve 200 ml pasta water.", "**Station B – Sauce:** Chop 4 anchovy fillets, mince 4 garlic cloves, chop 10 g ají panca paste, pit 80 g olives, rinse 30 g capers, chop 400 g canned San Marzano tomatoes.", "**Station C – Seafood:** Clean 300 g squid tubes (cut into rings) and 200 g shrimp."], "ingredients": ["400 g whole‑grain spaghetti, 4 anchovy fillets, 4 garlic cloves, 10 g ají panca paste, 80 g olives, 30 g capers, 400 g canned tomatoes, 300 g squid, 200 g shrimp, 5 g red pepper flakes, 30 ml olive oil, 5 ml red wine vinegar, 20 g parsley."], "method": ["**Make sauce:** In a large skillet, warm olive oil; melt anchovies and garlic until fragrant. Add ají panca paste and red pepper flakes; cook 1 min. Stir in tomatoes, olives and capers; simmer 10 min until thickened.", "**Cook seafood:** Add squid rings and shrimp to the sauce; cook 2–3 min until just opaque.", "**Combine:** Toss cooked spaghetti with sauce, adding reserved pasta water to loosen as needed. Finish with red wine vinegar and chopped parsley."], "why_this_works": "** Ají panca introduces a smoky, mild heat that complements the briny anchovies and olives. Whole‑grain pasta brings extra nutty flavour and fibre, and reserved pasta water emulsifies the sauce, helping it cling to each strand.", "plating": "& Pairing:** Twirl pasta into nests on warm plates; top with extra seafood pieces. Pair with a dry rosé or citrus‑infused sparkling water."}, {"title": "Whiskey Pecan Dark Chocolate Tart (American)", "servings": null, "active_time": "", "total_time": "", "mise_en_place": ["**Station A – Tart shell:** Combine 200 g whole‑wheat flour, 50 g almond flour, 30 g cocoa powder, 50 g raw sugar and 120 g cold butter. Rub to sandy crumbs; add 1 beaten egg and form a dough. Press into a 24 cm tart tin; chill 30 min.", "**Station B – Ganache:** Chop 250 g 70 % dark chocolate. Heat 250 ml heavy cream with 30 g honey until steaming; pour over chocolate and stir until smooth. Stir in 30 ml whiskey (optional) and 50 g butter.", "**Station C – Pecans:** Toast 150 g pecans; reserve 50 g for garnish."], "ingredients": ["Tart shell: 200 g whole‑wheat flour, 50 g almond flour, 30 g cocoa powder, 50 g raw sugar, 120 g butter, 1 egg, pinch salt.", "Filling: 250 g dark chocolate, 250 ml heavy cream, 30 g honey, 30 ml whiskey (optional), 50 g butter, 100 g toasted pecans.", "Garnish: 50 g toasted pecans, flaky sea salt."], "method": ["**Bake shell:** Blind‑bake chilled tart shell at 180 °C for 15 min with weights; remove weights and bake 10 min more until crisp. Cool.", "**Make ganache:** Combine hot cream and honey with chopped chocolate; stir until glossy. Stir in butter and whiskey until emulsified. Fold in 100 g chopped pecans.", "**Fill tart:** Pour ganache into cooled shell; smooth top. Arrange remaining pecans decoratively. Chill for 3 h until set.", "**Finish:** Sprinkle with flaky sea salt just before serving."], "why_this_works": "** Whole‑wheat and almond flours create a tender yet sturdy shell with nutty flavour. Honey lightly sweetens the ganache and aids emulsification. Whiskey adds complexity without excessive alcohol; to omit, replace with vanilla extract.", "plating": "& Pairing:** Slice tart with a hot knife for clean edges. Serve with a dollop of crème fraîche or Greek yoghurt. Pair with a small pour of tawny Port or black coffee."}, {"title": "Whole‑Grain Bagels (Base for breakfast)", "servings": null, "active_time": "", "total_time": "", "mise_en_place": [], "ingredients": [], "method": [], "why_this_works": null, "plating": null}];

export const i18n = {"title": {"en": "Personal Gourmet Kitchen", "es": "Cocina Gourmet Personal", "fr": "Cuisine Gourmande Personnelle", "zh": "个人美食厨房"}, "navFlavor": {"en": "Flavour Profile", "es": "Perfil de Sabor", "fr": "Profil de Saveur", "zh": "味觉档案"}, "navRecipes": {"en": "Recipes", "es": "Recetas", "fr": "Recettes", "zh": "食谱"}, "navCalendar": {"en": "Calendar", "es": "Calendario", "fr": "Calendrier", "zh": "日历"}, "navShopping": {"en": "Shopping List", "es": "Lista de Compras", "fr": "Liste d’achats", "zh": "购物清单"}, "selectLanguage": {"en": "Language", "es": "Idioma", "fr": "Langue", "zh": "语言"}, "chartTitle": {"en": "Your Flavour Spectrum", "es": "Tu Espectro de Sabores", "fr": "Votre Spectre de Saveurs", "zh": "您的味道光谱"}, "recipesTitle": {"en": "Recipe Library", "es": "Biblioteca de Recetas", "fr": "Bibliothèque de Recettes", "zh": "食谱库"}, "calendarTitle": {"en": "Meal Calendar", "es": "Calendario de Comidas", "fr": "Calendrier des Repas", "zh": "餐食日历"}, "shoppingTitle": {"en": "Consolidated Shopping List", "es": "Lista de Compras Consolidada", "fr": "Liste de Courses Consolidée", "zh": "汇总购物清单"}, "assignRecipe": {"en": "Assign recipe…", "es": "Asignar receta…", "fr": "Assigner une recette…", "zh": "分配食谱…"}, "noRecipe": {"en": "— None —", "es": "— Ninguno —", "fr": "— Aucune —", "zh": "— 无 —"}, "shoppingGenerate": {"en": "Generate List", "es": "Generar Lista", "fr": "Générer la liste", "zh": "生成清单"}, "downloadData": {"en": "Download Data", "es": "Descargar Datos", "fr": "Télécharger les données", "zh": "下载数据"}};

export const calendarAssignments = {};

export const shoppingCategories = {"produce": ["lettuce", "tomato", "avocado", "onion", "cilantro", "potato", "spinach", "mushroom", "radish", "chives", "lime", "lemon", "artichoke", "chili", "pepper", "garlic"], "proteins": ["beef", "lamb", "chicken", "turkey", "pork", "salmon", "trout", "tuna", "egg", "tofu", "prawn", "shrimp"], "dairy": ["butter", "cream", "cheese", "mozzarella", "parmesan", "yogurt", "milk"], "grains": ["rice", "quinoa", "pasta", "noodles", "bread", "muffins", "bagels", "tortilla", "gnocchi"], "pantry": ["vinegar", "oil", "tamari", "soy", "miso", "sauce", "broth", "stock", "flour", "sugar", "salt", "spice"], "beverages": ["wine", "beer", "water", "spritzer", "tea", "coffee"], "spices": ["cumin", "coriander", "bay leaves", "oregano", "basil", "pepper", "sesame"]};

