{"cmd":["bash","-lc","apply_patch <<'EOF'
*** Begin Patch
*** Add File: user_flavor_website/assets/js/app.js
+/*
+ * app.js
+ *
+ * This script orchestrates the user interface for the personal gourmet
+ * kitchen.  It imports data, renders charts and lists, manages
+ * multi‑language text, handles calendar assignments and assembles a
+ * consolidated shopping list.  No external libraries are required.
+ */
+
+import { flavorStats, recipes, i18n, calendarAssignments, shoppingCategories } from './data.js';
+
+// Global application state.  Additional properties may be added as needed.
+const state = {
+  lang: 'en',
+};
+
+/**
+ * Translate all elements annotated with `data-i18n` according to the
+ * current language stored in state.lang.  Fallback to English if a
+ * translation is missing.  After translation, dynamic sections
+ * (charts, lists) should be re-rendered to ensure labels match the
+ * selected language.
+ */
+function translateUI() {
+  document.querySelectorAll('[data-i18n]').forEach(el => {
+    const key = el.getAttribute('data-i18n');
+    const entry = i18n[key];
+    if (entry) {
+      el.textContent = entry[state.lang] || entry['en'] || '';
+    }
+  });
+}
+
+/**
+ * Render the flavour bar chart inside #flavor-chart.  Bars scale
+ * proportionally based on the largest value in flavorStats.  Each
+ * entry displays the flavour name and its relative intensity.
+ */
+function renderFlavorChart() {
+  const container = document.getElementById('flavor-chart');
+  container.innerHTML = '';
+  const maxValue = Math.max(...Object.values(flavorStats));
+  Object.entries(flavorStats).forEach(([flavour, value]) => {
+    const row = document.createElement('div');
+    row.className = 'flex items-center space-x-2';
+    const label = document.createElement('span');
+    label.className = 'w-24 capitalize text-sm text-emerald-800';
+    label.textContent = flavour;
+    const barContainer = document.createElement('div');
+    barContainer.className = 'flex-1 h-4 bg-emerald-200 rounded-full overflow-hidden';
+    const bar = document.createElement('div');
+    bar.className = 'h-full bg-emerald-600';
+    bar.style.width = `${(value / maxValue) * 100}%`;
+    barContainer.appendChild(bar);
+    const valueSpan = document.createElement('span');
+    valueSpan.className = 'w-12 text-right text-sm text-emerald-700';
+    valueSpan.textContent = value;
+    row.append(label, barContainer, valueSpan);
+    container.appendChild(row);
+  });
+}
+
+/**
+ * Render the recipe library.  Each recipe is displayed as a card
+ * containing its title.  Clicking a card opens a modal with
+ * detailed information.
+ */
+function renderRecipesList() {
+  const list = document.getElementById('recipes-list');
+  list.innerHTML = '';
+  recipes.forEach((recipe, idx) => {
+    const card = document.createElement('div');
+    card.className = 'bg-white/80 p-4 rounded-lg shadow hover:bg-white cursor-pointer transition';
+    card.dataset.index = idx;
+    const title = document.createElement('h3');
+    title.className = 'text-lg font-semibold text-emerald-800';
+    title.textContent = recipe.title;
+    card.appendChild(title);
+    card.addEventListener('click', () => {
+      showRecipeModal(idx);
+    });
+    list.appendChild(card);
+  });
+}
+
+/**
+ * Populate and display the recipe modal.
+ * @param {number} index Index of the recipe in the recipes array.
+ */
+function showRecipeModal(index) {
+  const recipe = recipes[index];
+  const modal = document.getElementById('recipe-modal');
+  document.getElementById('modal-title').textContent = recipe.title;
+  // Servings and times (if available)
+  let meta = '';
+  if (recipe.servings) meta += `Servings: ${recipe.servings}`;
+  if (recipe.active_time) meta += (meta ? ' | ' : '') + `Active: ${recipe.active_time}`;
+  if (recipe.total_time) meta += (meta ? ' | ' : '') + `Total: ${recipe.total_time}`;
+  document.getElementById('modal-servings').textContent = meta;
+  // Mise en place
+  const miseDiv = document.getElementById('modal-mise');
+  miseDiv.innerHTML = '';
+  if (recipe.mise_en_place && recipe.mise_en_place.length) {
+    const h = document.createElement('h4');
+    h.className = 'font-semibold text-emerald-700 mb-1';
+    h.textContent = 'Mise en place';
+    miseDiv.appendChild(h);
+    const ul = document.createElement('ul');
+    ul.className = 'list-disc pl-5 space-y-1 text-sm';
+    recipe.mise_en_place.forEach(item => {
+      const li = document.createElement('li');
+      li.textContent = item;
+      ul.appendChild(li);
+    });
+    miseDiv.appendChild(ul);
+  }
+  // Ingredients
+  const ingDiv = document.getElementById('modal-ingredients');
+  ingDiv.innerHTML = '';
+  if (recipe.ingredients && recipe.ingredients.length) {
+    const h = document.createElement('h4');
+    h.className = 'font-semibold text-emerald-700 mb-1';
+    h.textContent = 'Ingredients';
+    ingDiv.appendChild(h);
+    const ul = document.createElement('ul');
+    ul.className = 'list-disc pl-5 space-y-1 text-sm';
+    recipe.ingredients.forEach(item => {
+      const li = document.createElement('li');
+      li.textContent = item;
+      ul.appendChild(li);
+    });
+    ingDiv.appendChild(ul);
+  }
+  // Method
+  const methodDiv = document.getElementById('modal-method');
+  methodDiv.innerHTML = '';
+  if (recipe.method && recipe.method.length) {
+    const h = document.createElement('h4');
+    h.className = 'font-semibold text-emerald-700 mb-1';
+    h.textContent = 'Method';
+    methodDiv.appendChild(h);
+    const ol = document.createElement('ol');
+    ol.className = 'list-decimal pl-5 space-y-1 text-sm';
+    recipe.method.forEach(item => {
+      const li = document.createElement('li');
+      li.textContent = item;
+      ol.appendChild(li);
+    });
+    methodDiv.appendChild(ol);
+  }
+  // Why this works
+  const whyDiv = document.getElementById('modal-why');
+  whyDiv.innerHTML = '';
+  if (recipe.why_this_works) {
+    whyDiv.innerHTML = recipe.why_this_works;
+  }
+  // Plating & pairing
+  const platingDiv = document.getElementById('modal-plating');
+  platingDiv.innerHTML = '';
+  if (recipe.plating) {
+    platingDiv.innerHTML = recipe.plating;
+  }
+  modal.classList.remove('hidden');
+}
+
+/** Close the recipe modal. */
+function closeModal() {
+  document.getElementById('recipe-modal').classList.add('hidden');
+}
+
+/**
+ * Render a four‑week calendar (28 days).  Each cell contains four
+ * dropdowns for breakfast, lunch, dinner and snack.  Recipes are
+ * referenced by index.  Selections update the calendarAssignments object.
+ */
+function renderCalendar() {
+  const grid = document.getElementById('calendar-grid');
+  grid.innerHTML = '';
+  // Determine first day of current month and number of days; fall back to 28
+  const today = new Date();
+  const year = today.getFullYear();
+  const month = today.getMonth();
+  const numDays = 28; // four weeks
+  for (let day = 1; day <= numDays; day++) {
+    const cell = document.createElement('div');
+    cell.className = 'bg-white/70 p-2 rounded-lg shadow flex flex-col space-y-1';
+    const header = document.createElement('div');
+    header.className = 'font-semibold text-emerald-700';
+    header.textContent = day;
+    cell.appendChild(header);
+    // Meal times
+    ['breakfast','lunch','dinner','snack'].forEach(meal => {
+      const select = document.createElement('select');
+      select.className = 'w-full mt-1 p-1 rounded border border-emerald-300 text-sm';
+      const noneOpt = document.createElement('option');
+      noneOpt.value = '';
+      noneOpt.textContent = i18n['noRecipe'][state.lang] || i18n['noRecipe']['en'];
+      select.appendChild(noneOpt);
+      recipes.forEach((r, idx) => {
+        const opt = document.createElement('option');
+        opt.value = idx;
+        opt.textContent = r.title;
+        select.appendChild(opt);
+      });
+      // Determine iso date string
+      const isoDate = new Date(year, month, day).toISOString().split('T')[0];
+      // Initialise calendarAssignments entry
+      if (!calendarAssignments[isoDate]) calendarAssignments[isoDate] = {};
+      // Prepopulate select value
+      if (calendarAssignments[isoDate][meal] !== undefined && calendarAssignments[isoDate][meal] !== null) {
+        select.value = calendarAssignments[isoDate][meal];
+      }
+      // Listen for change
+      select.addEventListener('change', () => {
+        const val = select.value === '' ? null : parseInt(select.value);
+        calendarAssignments[isoDate][meal] = val;
+      });
+      const label = document.createElement('label');
+      label.className = 'text-xs text-emerald-700';
+      label.textContent = meal.charAt(0).toUpperCase() + meal.slice(1);
+      const wrapper = document.createElement('div');
+      wrapper.className = 'flex flex-col';
+      wrapper.appendChild(label);
+      wrapper.appendChild(select);
+      cell.appendChild(wrapper);
+    });
+    grid.appendChild(cell);
+  }
+}
+
+/**
+ * Generate the shopping list based on current calendar assignments.
+ * Ingredients are aggregated and grouped into categories defined in
+ * shoppingCategories.  Duplicate lines are combined with a count.
+ */
+function generateShoppingList() {
+  // Aggregate ingredient lines from selected recipes
+  const ingredientCounts = {};
+  Object.values(calendarAssignments).forEach(meals => {
+    Object.values(meals).forEach(idx => {
+      if (idx !== null && idx !== undefined) {
+        const recipe = recipes[idx];
+        if (recipe.ingredients) {
+          recipe.ingredients.forEach(line => {
+            const key = line.toLowerCase();
+            if (!ingredientCounts[key]) ingredientCounts[key] = 0;
+            ingredientCounts[key] += 1;
+          });
+        }
+      }
+    });
+  });
+  // Classify ingredients
+  const categories = {};
+  Object.keys(shoppingCategories).forEach(cat => categories[cat] = []);
+  categories['others'] = [];
+  for (const [line, count] of Object.entries(ingredientCounts)) {
+    let placed = false;
+    for (const [cat, keywords] of Object.entries(shoppingCategories)) {
+      if (keywords.some(kw => line.includes(kw))) {
+        categories[cat].push({line, count});
+        placed = true;
+        break;
+      }
+    }
+    if (!placed) {
+      categories['others'].push({line, count});
+    }
+  }
+  // Render the list
+  const container = document.getElementById('shopping-content');
+  container.innerHTML = '';
+  Object.entries(categories).forEach(([cat, items]) => {
+    if (items.length === 0) return;
+    const section = document.createElement('div');
+    const heading = document.createElement('h4');
+    heading.className = 'font-semibold text-emerald-700 capitalize';
+    heading.textContent = cat;
+    section.appendChild(heading);
+    const ul = document.createElement('ul');
+    ul.className = 'list-disc pl-5 space-y-1 text-sm';
+    items.forEach(item => {
+      const li = document.createElement('li');
+      li.textContent = `${item.count}× ${item.line}`;
+      ul.appendChild(li);
+    });
+    section.appendChild(ul);
+    container.appendChild(section);
+  });
+}
+
+/**
+ * Show a given section by ID and hide others.  Buttons store the
+ * target section via their `data-section` attribute.  Active button
+ * gets a highlighted background.
+ * @param {string} id Section identifier suffix (flavor, recipes, calendar, shopping)
+ */
+function showSection(id) {
+  ['flavor','recipes','calendar','shopping'].forEach(sec => {
+    const section = document.getElementById(`section-${sec}`);
+    if (section) section.classList.toggle('hidden', sec !== id);
+  });
+  // Highlight navigation button
+  document.querySelectorAll('aside button').forEach(btn => {
+    const match = btn.getAttribute('data-section') === id;
+    btn.classList.toggle('bg-emerald-300', match);
+  });
+}
+
+/**
+ * Bind event listeners for UI interactions.
+ */
+function bindEvents() {
+  // Navigation buttons
+  document.getElementById('btn-flavor').addEventListener('click', () => showSection('flavor'));
+  document.getElementById('btn-recipes').addEventListener('click', () => showSection('recipes'));
+  document.getElementById('btn-calendar').addEventListener('click', () => showSection('calendar'));
+  document.getElementById('btn-shopping').addEventListener('click', () => showSection('shopping'));
+  // Modal close
+  document.getElementById('modal-close').addEventListener('click', closeModal);
+  // Language selector
+  document.getElementById('language-select').addEventListener('change', e => {
+    state.lang = e.target.value;
+    translateUI();
+    // Re-render dynamic UI to update labels
+    renderFlavorChart();
+    renderCalendar();
+    // Note: recipe titles remain in original language; translation could be added later
+  });
+  // Shopping list generation
+  document.getElementById('generate-list').addEventListener('click', generateShoppingList);
+}
+
+/** Initialise the application once the DOM is ready. */
+function init() {
+  translateUI();
+  renderFlavorChart();
+  renderRecipesList();
+  renderCalendar();
+  bindEvents();
+  // Default section
+  showSection('flavor');
+}
+
+document.addEventListener('DOMContentLoaded', init);
*** End Patch
EOF
"]}

